package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayUtils_add_TriageGen0Test {

    @Test
    public void testAdd_WithExistingArray() {
        String[] array = {"a", "b", "c"};
        String element = "d";
        String[] result = ArrayUtils.add(array, element);

        assertArrayEquals(new String[]{"a", "b", "c", "d"}, result);
        assertNotSame(array, result); // Should be a new array
        assertEquals(4, result.length);
    }

    @Test
    public void testAdd_WithNullArrayAndNonNullElement() {
        Integer element = 1;
        Integer[] result = ArrayUtils.add(null, element);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertEquals(Integer.valueOf(1), result[0]);
    }

    @Test
    public void testAdd_WithNullArrayAndNullElement() {
        // This triggers the else { type = Object.class; } branch
        Object[] result = ArrayUtils.add(null, null);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }

    @Test
    public void testAdd_WithEmptyArray() {
        String[] array = {};
        String element = "new";
        String[] result = ArrayUtils.add(array, element);

        assertArrayEquals(new String[]{"new"}, result);
    }

    @Test
    public void testAdd_WithDifferentTypes_Integer() {
        Integer[] array = {1, 2};
        Integer element = 3;
        Integer[] result = ArrayUtils.add(array, element);

        assertArrayEquals(new Integer[]{1, 2, 3}, result);
    }

    @Test
    public void testAdd_WithDouble() {
        Double[] array = {1.1, 2.2};
        Double element = 3.3;
        Double[] result = ArrayUtils.add(array, element);

        assertArrayEquals(new Double[]{1.1, 2.2, 3.3}, result, 0.0001);
    }

    @Test
    public void testAdd_WithBoolean() {
        Boolean[] array = {true, false};
        Boolean element = true;
        Boolean[] result = ArrayUtils.add(array, element);

        assertArrayEquals(new Boolean[]{true, false, true}, result);
    }
}
